"""Product analytics dashboard: conversion statistics over customer sessions."""


def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    out = []
    flags = {"1": True, "0": False, "": None}
    for line_number, line in enumerate(lines, 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: invalid day") from exc
        if flag not in flags:
            raise ValueError(f"line {line_number}: invalid converted value")
        out.append({"id": id_, "day": day, "converted": flags[flag]})
    return out


def dedupe_sessions(events):
    """Remove duplicate sessions. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Daily counts of converted sessions. See SPEC.md section 6."""
    counts = {}
    for e in events:
        if start_day <= e["day"] <= end_day and e["converted"] is True:
            counts[e["day"]] = counts.get(e["day"], 0) + 1
    return [counts.get(day, 0) for day in range(start_day, end_day + 1)]
