def test_conversion_rate_counts_none_in_denominator():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([{"converted": None}, {"converted": False}]) == 0.0
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions_and_handles_empty_groups():
    groups = {"a": [{"converted": True}], "b": [{"converted": False}] * 3, "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (5, 6)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_flags_whitespace_and_skipped_lines():
    lines = ["\n", "  # comment,ignored,1", " a , 2 , 1 ", "b, 3, 0", "c,4,  "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 2, "converted": True},
        {"id": "b", "day": 3, "converted": False},
        {"id": "c", "day": 4, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,nope,1", "a,1,yes"])
def test_parse_error_reports_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["", " # comment", "a,1,1", bad_line])


def test_dedupe_keeps_last_duplicate_and_sorts_by_day_then_id():
    events = [
        {"id": "a", "day": 1, "converted": True},
        {"id": "c", "day": 2, "converted": True},
        {"id": "b", "day": 2, "converted": False},
        {"id": "a", "day": 2, "converted": None},
    ]
    assert dedupe_sessions(events) == [events[3], events[2], events[1]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_range_and_gaps():
    events = [
        {"day": 0, "converted": True},
        {"day": 1, "converted": True},
        {"day": 1, "converted": True},
        {"day": 2, "converted": None},
        {"day": 3, "converted": False},
        {"day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 0]
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_weights_rounds_and_uses_calendar_days():
    groups = {
        "empty": [],
        "a": [{"day": 1, "converted": True}],
        "b": [{"day": 4, "converted": False}, {"day": 4, "converted": False}],
    }
    assert campaign_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 4) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "empty": [],
        "b": [{"converted": False}],
        "a": [{"converted": True}],
    }
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "b": [{"converted": None}], "a": [{"converted": True}]}
    result = conversion_rate_by_group(groups)
    assert list(result.items()) == [("a", 1.0), ("b", 0.0), ("z", None)]


def test_longest_conversion_streak_resets_on_zero_and_negative():
    assert longest_conversion_streak([1, 2, 0, 1, -1, 1, 2, 3]) == 3
    assert longest_conversion_streak([0, -1]) == 0
    assert longest_conversion_streak([]) == 0
